import{_ as a,o as i,c as o,a3 as l}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"Agent 配置","description":"哪吒监控 V2 Agent YAML 配置参考，覆盖 Dashboard 地址、连接密钥、TLS、上报周期、系统指标、自定义 IP API、更新和命令/NAT 禁用选项。","frontmatter":{"description":"哪吒监控 V2 Agent YAML 配置参考，覆盖 Dashboard 地址、连接密钥、TLS、上报周期、系统指标、自定义 IP API、更新和命令/NAT 禁用选项。","outline":"deep"},"headers":[],"relativePath":"configuration/agent.md","filePath":"configuration/agent.md","lastUpdated":1792850916000}'),t={name:"configuration/agent.md"};function d(s,e,c,r,n,p){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="agent-配置" tabindex="-1">Agent 配置 <a class="header-anchor" href="#agent-配置" aria-label="Permalink to &quot;Agent 配置&quot;">​</a></h1><p>Agent 配置文件格式为 YAML。</p><p>在管理后台中，可以对 Agent 的配置进行修改并直接应用；也可以通过 API 批量下发配置项，详见 <a href="/developer/api.html">API 文档</a>。</p><hr><h2 id="文件与生效值" tabindex="-1">文件与生效值 <a class="header-anchor" href="#文件与生效值" aria-label="Permalink to &quot;文件与生效值&quot;">​</a></h2><p>Agent 默认读取可执行文件旁的 <code>config.yml</code>，用 <code>-c</code> 指定其它路径。环境变量命名和优先级与 Dashboard 不同，先读<a href="/configuration/environment.html">加载规则</a>。下文列出缺省值，必填身份字段另行说明。</p><h2 id="选项" tabindex="-1">选项 <a class="header-anchor" href="#选项" aria-label="Permalink to &quot;选项&quot;">​</a></h2><ul><li><h5 id="client-secret" tabindex="-1"><strong><code>client_secret</code></strong> <a class="header-anchor" href="#client-secret" aria-label="Permalink to &quot;**`client_secret`**&quot;">​</a></h5><ul><li><p>类型：<code>string</code>；默认：必填，无可用默认值。</p></li><li><p>用于与 Dashboard 进行安全通信的客户端密钥。</p></li><li><p>连接密钥与用户绑定。当前前台没有单独的“复制连接密钥”入口，通常应直接使用服务器页面生成的安装命令，或从该命令中的 <code>NZ_CLIENT_SECRET</code> 提取。</p></li><li><p>管理员如需为其他用户手动配置 Agent，可通过管理接口读取对应用户的 <code>agent_secret</code>，不要继续使用配置文件中的全局 <code>agent_secret_key</code>。</p></li><li><p>此参数填写错误时，Agent 无法通过 Dashboard 鉴权。</p></li></ul></li><li><h5 id="debug" tabindex="-1"><strong><code>debug</code></strong> <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;**`debug`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时启用日志。</p></li></ul></li><li><h5 id="disable-auto-update" tabindex="-1"><strong><code>disable_auto_update</code></strong> <a class="header-anchor" href="#disable-auto-update" aria-label="Permalink to &quot;**`disable_auto_update`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时禁用 Agent 的自动更新功能，增强系统稳定性和安全性。</p></li></ul></li><li><h5 id="disable-command-execute" tabindex="-1"><strong><code>disable_command_execute</code></strong> <a class="header-anchor" href="#disable-command-execute" aria-label="Permalink to &quot;**`disable_command_execute`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时拒绝命令执行、在线终端、文件管理和 MCP 文件/命令操作，也拒绝远程读取与应用配置。解除此限制需要在主机本地修改并重启。</p></li></ul></li><li><h5 id="disable-force-update" tabindex="-1"><strong><code>disable_force_update</code></strong> <a class="header-anchor" href="#disable-force-update" aria-label="Permalink to &quot;**`disable_force_update`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时拒绝 Dashboard 下发的强制升级；不关闭定期自动检查。要完全改为自行维护，另设 <code>disable_auto_update: true</code>。</p></li></ul></li><li><h5 id="disable-nat" tabindex="-1"><strong><code>disable_nat</code></strong> <a class="header-anchor" href="#disable-nat" aria-label="Permalink to &quot;**`disable_nat`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时 Agent 不再接受面板下达的 <strong>内网穿透</strong> 任务。</p></li></ul></li><li><h5 id="disable-send-query" tabindex="-1"><strong><code>disable_send_query</code></strong> <a class="header-anchor" href="#disable-send-query" aria-label="Permalink to &quot;**`disable_send_query`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时 Agent 不再接受面板下达的 <code>TCP Ping</code>、<code>ICMP Ping</code> 和 <code>HTTP GET</code> 任务。</p></li></ul></li><li><h5 id="gpu" tabindex="-1"><strong><code>gpu</code></strong> <a class="header-anchor" href="#gpu" aria-label="Permalink to &quot;**`gpu`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时启用 GPU 监控。Linux NVIDIA 还支持逐卡显存上报；其他平台/厂商仍可能只有使用率。</p></li><li><p>注意：启用 GPU 监控可能需要安装额外依赖，详细信息参考：<a href="/guide/q9.html">启用 GPU 监控</a>。</p></li></ul></li><li><h5 id="insecure-tls" tabindex="-1"><strong><code>insecure_tls</code></strong> <a class="header-anchor" href="#insecure-tls" aria-label="Permalink to &quot;**`insecure_tls`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时禁用证书检查，适用于使用自签名证书的场景。</p></li></ul></li><li><h5 id="ip-report-period" tabindex="-1"><strong><code>ip_report_period</code></strong> <a class="header-anchor" href="#ip-report-period" aria-label="Permalink to &quot;**`ip_report_period`**&quot;">​</a></h5><ul><li><p>类型：<code>integer</code>；默认：<code>1800</code>。</p></li><li><p>设置本地 IP 更新间隔时间（秒）。默认值为 <code>1800</code> 秒（30 分钟）。</p></li><li><p><code>0</code> 回退为 <code>1800</code>，非零且小于 <code>30</code> 时按 <code>30</code> 秒处理。</p></li></ul></li><li><h5 id="report-delay" tabindex="-1"><strong><code>report_delay</code></strong> <a class="header-anchor" href="#report-delay" aria-label="Permalink to &quot;**`report_delay`**&quot;">​</a></h5><ul><li><p>类型：<code>integer</code>；默认：<code>3</code>。</p></li><li><p>状态上报间隔（秒），<code>0</code> 回退为 <code>3</code>，有效范围为 <code>1</code>–<code>4</code>；其它越界值校验失败，并非自动截断。</p></li></ul></li><li><h5 id="server" tabindex="-1"><strong><code>server</code></strong> <a class="header-anchor" href="#server" aria-label="Permalink to &quot;**`server`**&quot;">​</a></h5><ul><li><p>类型：<code>string</code>；默认：必填，无可用默认值。</p></li><li><p>格式为 <code>host:port</code>，不包含 <code>http://</code>、<code>https://</code> 或路径。IPv6 使用 <code>[IPv6]:port</code>；TLS 由独立的 <code>tls</code> 控制。</p></li></ul></li><li><h5 id="skip-connection-count" tabindex="-1"><strong><code>skip_connection_count</code></strong> <a class="header-anchor" href="#skip-connection-count" aria-label="Permalink to &quot;**`skip_connection_count`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时禁用网络连接数的监控，适用于高连接数或资源受限的环境。</p></li></ul></li><li><h5 id="skip-procs-count" tabindex="-1"><strong><code>skip_procs_count</code></strong> <a class="header-anchor" href="#skip-procs-count" aria-label="Permalink to &quot;**`skip_procs_count`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时禁用进程数的监控，以降低资源占用。</p></li></ul></li><li><h5 id="temperature" tabindex="-1"><strong><code>temperature</code></strong> <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;**`temperature`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时启用硬件温度监控（仅支持部分硬件，部分 VPS 可能无法获取温度信息）。</p></li></ul></li><li><h5 id="tls" tabindex="-1"><strong><code>tls</code></strong> <a class="header-anchor" href="#tls" aria-label="Permalink to &quot;**`tls`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时启用 Agent 与 Dashboard 间的通信 SSL/TLS 加密。</p></li><li><p>如果 Agent 使用 Nginx 反向代理且启用了 SSL/TLS 配置，请开启此选项。</p></li></ul></li><li><h5 id="hard-drive-partition-allowlist" tabindex="-1"><strong><code>hard_drive_partition_allowlist</code></strong> <a class="header-anchor" href="#hard-drive-partition-allowlist" aria-label="Permalink to &quot;**`hard_drive_partition_allowlist`**&quot;">​</a></h5><ul><li><p>类型：<code>string[]</code>；默认：<code>[]</code>。</p></li><li><p>一个字符串数组，用于指定需要监控的硬盘分区列表。</p></li><li><p>若指定此参数，将仅对列出的分区进行监控。</p></li></ul></li><li><h5 id="nic-allowlist" tabindex="-1"><strong><code>nic_allowlist</code></strong> <a class="header-anchor" href="#nic-allowlist" aria-label="Permalink to &quot;**`nic_allowlist`**&quot;">​</a></h5><ul><li><p>类型：<code>map[string]bool</code>；默认：<code>{}</code>。</p></li><li><p>一个 <code>map[string]bool</code> 类型的允许列表，用于指定需要监控的网卡。</p></li><li><p>键为网卡名称，值为 <code>true</code> 表示允许监控，<code>false</code> 表示不监控。</p></li><li><p>非空时只有值为 <code>true</code> 的接口计入；未列出的接口也排除。留空时采用内置过滤，会排除常见回环、隧道和容器接口，并非所有虚拟网卡。</p></li></ul></li><li><h5 id="use-gitee-to-upgrade" tabindex="-1"><strong><code>use_gitee_to_upgrade</code></strong> <a class="header-anchor" href="#use-gitee-to-upgrade" aria-label="Permalink to &quot;**`use_gitee_to_upgrade`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时使用 Gitee 仓库作为自动更新源，对中国大陆服务器更为友好。</p></li></ul></li><li><h5 id="use-atomgit-to-upgrade" tabindex="-1"><strong><code>use_atomgit_to_upgrade</code></strong> <a class="header-anchor" href="#use-atomgit-to-upgrade" aria-label="Permalink to &quot;**`use_atomgit_to_upgrade`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时使用 AtomGit 仓库作为自动更新源。通常只需要在默认更新源访问不稳定时启用。</p></li></ul></li><li><h5 id="use-ipv6-country-code" tabindex="-1"><strong><code>use_ipv6_country_code</code></strong> <a class="header-anchor" href="#use-ipv6-country-code" aria-label="Permalink to &quot;**`use_ipv6_country_code`**&quot;">​</a></h5><ul><li><p>类型：<code>bool</code>；默认：<code>false</code>。</p></li><li><p>当为 <code>true</code> 时强制使用 IPv6 地址查询国家代码（默认使用 IPv4）。</p></li></ul></li><li><h5 id="uuid" tabindex="-1"><strong><code>uuid</code></strong> <a class="header-anchor" href="#uuid" aria-label="Permalink to &quot;**`uuid`**&quot;">​</a></h5><ul><li><p>类型：<code>string</code>；默认：留空生成并保存。</p></li><li><p>当前 Agent 的唯一标识参数，用于 Dashboard 识别数据来源。</p></li><li><p>若需替换 Dashboard 中已存在的 Agent，可以手动设置此参数。</p></li></ul></li><li><h5 id="dns" tabindex="-1"><strong><code>dns</code></strong> <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;**`dns`**&quot;">​</a></h5><ul><li><p>类型：<code>string[]</code>；默认：<code>[]</code>。</p></li><li><p>一个字符串数组，用于设置自定义 DNS 服务器列表。</p></li><li><p>指定后，Agent 将优先使用此列表中的 DNS 服务器解析域名。</p></li></ul></li><li><h5 id="custom-ip-api" tabindex="-1"><strong><code>custom_ip_api</code></strong> <a class="header-anchor" href="#custom-ip-api" aria-label="Permalink to &quot;**`custom_ip_api`**&quot;">​</a></h5><ul><li><p>类型：<code>string[]</code>；默认：<code>[]</code>。</p></li><li><p>一个字符串数组，用于指定自定义 IP 查询 API 列表。</p></li><li><p>API 应返回纯 IP 文本，或兼容 Cloudflare trace 的 <code>ip=</code> 行；任意 JSON 地址接口不一定兼容。它们用于公网 IP 发现，不是国家地理位置 API。</p></li><li><p>每个地址都必须能被解析为 URL，并使用 <code>http</code> 或 <code>https</code> 协议；不符合要求的地址会导致 Agent 启动失败，或导致远程配置无法应用。</p></li></ul></li><li><h5 id="self-update-period" tabindex="-1"><strong><code>self_update_period</code></strong> <a class="header-anchor" href="#self-update-period" aria-label="Permalink to &quot;**`self_update_period`**&quot;">​</a></h5><ul><li>类型：<code>integer</code>；默认：<code>0</code>。</li><li>手动设置更新间隔（分钟）。</li><li><code>0</code> 使用随机周期（30 分钟起、不满 90 分钟）；正值按分钟固定。更新开关和周期在启动时读取，改后完整重启以可靠生效。</li></ul></li></ul><hr><h2 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h2><p>在修改配置文件中的参数后，需要重新启动 Agent 服务以使更改生效。可以使用 Agent 的内置服务管理功能或者手动重启。</p><h3 id="使用内置服务管理" tabindex="-1">使用内置服务管理 <a class="header-anchor" href="#使用内置服务管理" aria-label="Permalink to &quot;使用内置服务管理&quot;">​</a></h3><p>可以直接输入以下命令重启默认 Agent 服务：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./nezha-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p>对于多个 Agent 服务的情况，可以指定对应的配置文件：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./nezha-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config-6sc1f.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><h3 id="手动管理" tabindex="-1">手动管理 <a class="header-anchor" href="#手动管理" aria-label="Permalink to &quot;手动管理&quot;">​</a></h3><ol><li><p><strong>重新启动服务</strong><br> 运行以下命令重新启动默认的第一个 Agent 服务：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-agent.service</span></span></code></pre></div></li><li><p><strong>多 Agent 服务的情况</strong><br> 如果同一服务器上运行了多个 Agent 服务，请先列出所有 Agent 服务的名称：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-units</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type=service</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-agent</span></span></code></pre></div><p>然后分别使用以下命令重新启动对应的 Agent 服务：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">service-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>将 <code>&lt;service-name&gt;</code> 替换为实际列出的名称。内置服务管理按二进制名称命名，非默认配置追加配置路径哈希，不要假定存在 <code>@2</code> 实例。</p></li></ol><h2 id="更新源与应用边界" tabindex="-1">更新源与应用边界 <a class="header-anchor" href="#更新源与应用边界" aria-label="Permalink to &quot;更新源与应用边界&quot;">​</a></h2><p>两个镜像开关同时开启时优先 Gitee；都关闭时仍可能按国家信息选择镜像，否则使用 GitHub。远程配置的应答、约 10 秒延迟应用和落盘/重连是不同阶段，详见<a href="/configuration/environment.html">配置加载</a>。<code>disable_command_execute</code> 不是仅禁用 shell 的开关；启用前要保留本机恢复入口。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/guide/agent.html">Agent 安装</a></li><li><a href="/guide/architecture.html">架构与数据流</a></li><li><a href="/guide/security.html">安全与隐私</a></li><li><a href="/guide/agentq.html">Agent 常见问题</a></li></ul>',22)])])}const g=a(t,[["render",d]]);export{u as __pageData,g as default};
